-- Seed mindset path Gumlet-hosted videos.
-- Source: scripts/data/mindsets-gumlet-videos.json
-- Generated by scripts/generate-mindsets-gumlet-migration.py from scripts/data/mindsets-gumlet-videos.json.
-- Removes the temporary 'gumlet-bend-the-world-test' row (if any) before the upsert.

do $$
declare
  expected_count int := 21;
  actual_count int;
  linked_count int;
begin
  if not exists (select 1 from public.categories where slug = 'mindsets') then
    raise exception 'Missing required category: mindsets';
  end if;

  delete from public.content
   where id = 'gumlet-bend-the-world-test'
     and id <> all (array['mindsets-gumlet-001', 'mindsets-gumlet-002', 'mindsets-gumlet-003', 'mindsets-gumlet-004', 'mindsets-gumlet-005', 'mindsets-gumlet-006', 'mindsets-gumlet-007', 'mindsets-gumlet-008', 'mindsets-gumlet-009', 'mindsets-gumlet-010', 'mindsets-gumlet-011', 'mindsets-gumlet-012', 'mindsets-gumlet-013', 'mindsets-gumlet-014', 'mindsets-gumlet-015', 'mindsets-gumlet-016', 'mindsets-gumlet-017', 'mindsets-gumlet-018', 'mindsets-gumlet-019', 'mindsets-gumlet-020', 'mindsets-gumlet-021']);

  insert into public.content (
    id,
    slug,
    title,
    description,
    content_type,
    thumbnail_url,
    video_url,
    video_orientation,
    video_duration,
    published_at,
    is_published,
    why_it_matters,
    planning_connection,
    takeaway,
    reflection
  )
  values
    ('mindsets-gumlet-001', 'bend-the-world', 'Bend the world', 'A founder describes Steve Jobs'' reality distortion field: the way deep belief in what''s possible quietly pulls a team into doing what looked impossible.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a3589ec653eb39ce727/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a3589ec653eb39ce727?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 53, now() - (1 * interval '1 second'), true, 'Most people accept the world as it is and try to fit into it. The clip shows that the strongest predictor of pulling off something big is the unspoken belief that the rules are more bendable than they look.', 'If you assume your future is something that happens to you, your planning becomes mostly defensive. If you assume parts of it are yours to shape, you start asking different questions about what you''d actually attempt.', 'Belief is upstream of action. People who think the world can move usually find a way to move it.', 'Most people quietly assume the world is fixed and they just play a role inside it. As you think about a goal that feels out of reach right now, what would change if you treated the rules around it as more bendable than they look?'),
    ('mindsets-gumlet-002', 'what-is-an-ai-agent', 'What is an AI agent?', 'A founder explains the difference between a chatbot you go back-and-forth with and an AI agent that takes a single high-level goal and figures out the steps on its own.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a35a2314e1a99735465/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a35a2314e1a99735465?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 38, now() - (2 * interval '1 second'), true, 'AI literacy is becoming a baseline skill for almost every career path. Knowing the difference between a chat tool and an agent shapes what work you can actually offload to AI.', 'The jobs that will feel safest in five years are the ones where you can clearly describe a goal, evaluate the output, and direct an agent toward better work. That is a learnable skill, not a talent.', 'Chatbots take instructions step by step. Agents take a goal and pick the steps themselves.', 'AI is shifting from tools you operate to tools you delegate to. As you think about a project or task you currently do by hand, what is one piece of it you could clearly hand off to an agent if you described the goal well enough?'),
    ('mindsets-gumlet-003', 'anxiety-vs-excitement', 'Anxiety vs. excitement', 'A communication researcher shares an experiment where students sang into accuracy software. The group that said ''I''m excited'' before singing outperformed the group that said ''I''m nervous'' by a wide margin.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a356d3b523a974ebecd/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a356d3b523a974ebecd?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 64, now() - (3 * interval '1 second'), true, 'Nerves and excitement feel almost identical in the body. The label you give that feeling changes how you perform under it, which matters for interviews, presentations, and first days.', 'A lot of opportunity rests on how you show up in high-pressure moments. Reframing ''I''m nervous'' as ''I''m excited'' is a free, repeatable tool you can use on anything from a job interview to a tryout.', 'Excitement and anxiety share the same body signals. Naming it excitement reliably moves your performance up.', 'Your body cannot easily tell anxiety apart from excitement; the difference is mostly the story you tell about it. As you think about something coming up that makes you nervous, what would change if you walked in saying ''I''m excited'' out loud?'),
    ('mindsets-gumlet-004', 'bias-to-action', 'Bias to action', 'A founder argues that most people confuse thinking with working. His edge is shortening the time between thinking about a thing and doing the thing.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a356d3b523a974ebecf/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a356d3b523a974ebecf?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 45, now() - (4 * interval '1 second'), true, 'Speed is often what separates students who get unstuck from students who stay stuck. Three sloppy attempts will teach you more than three weeks of planning.', 'Career planning is full of decisions you cannot fully think your way through. The faster you turn an option into a small action, the faster you learn whether it is actually for you.', 'Thinking is not working. The fastest path to clarity is usually a small action you can take this week.', 'It is easy to confuse thinking about a decision with making progress on it. As you think about a question you have been turning over for a while, what is one small experiment you could run this week to actually learn something about it?'),
    ('mindsets-gumlet-005', 'learn-dont-earn-when-young', 'Learn, don''t earn, when you''re young', 'A founder pushes back on the idea that your 20s are about chasing salary. He argues that maximizing what you learn beats maximizing what you earn at that stage.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a35a2314e1a9973546a/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a35a2314e1a9973546a?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 53, now() - (5 * interval '1 second'), true, 'Early career choices compound. Picking a job for what it teaches you usually pays off more over a decade than picking it for the starting paycheck.', 'When comparing two first jobs, the salary gap rarely matters as much as the gap in what you''ll learn and who you''ll work near. Treat the first three years as paid tuition.', 'In your first few years of work, optimize for what you learn and who you learn from, not for what you earn.', 'Early in a career, learning compounds far faster than salary. As you think about your next step after school, what would change if you ranked your options by how much you''d learn instead of how much you''d earn?'),
    ('mindsets-gumlet-006', 'the-importance-of-perspective', 'The importance of perspective', 'A finance writer points out that most decisions you''d fiercely disagree with would feel rational if you''d grown up with the same family, era, and circumstances as the person making them.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a356d3b523a974ebed1/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a356d3b523a974ebed1?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 51, now() - (6 * interval '1 second'), true, 'It is easy to judge other people''s choices about money, school, or career. The clip shows how much of any decision is shaped by context you can''t fully see from the outside.', 'Your own plan is being built inside a context that is partly invisible to you. Asking ''what would I do differently if I''d been raised somewhere else?'' surfaces assumptions worth checking.', 'Most decisions other people make would feel rational from inside their life. Yours would too.', 'We tend to forget how much of any decision is shaped by context we did not pick. As you think about a recent choice of your own, what part of it might look different if you had grown up in a different family, place, or era?'),
    ('mindsets-gumlet-007', 'start-at-the-end', 'Start at the end', 'A storytelling coach argues that good keynotes, decks, and stories are designed backward from the line you want the audience to walk out remembering.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a35a2314e1a99735467/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a35a2314e1a99735467?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 84, now() - (7 * interval '1 second'), true, 'Most students write essays, slides, and talks by adding content forward until they run out of time. Starting from the ending forces you to know what you''re actually saying.', 'The same backward-design trick works for plans. Decide what ''success'' looks like at the end of a term or a job search, then work backward from there to today.', 'If you try to say a bunch of things, you say nothing. Pick the one line you want to land and design backward from there.', 'Most projects fall apart because they aim at too many endings at once. As you think about something you''re working on right now, what is the single sentence you''d want a reader or audience to remember at the very end?'),
    ('mindsets-gumlet-008', 'build-an-app-with-chatgpt', 'Build an app with ChatGPT', 'A young builder walks through how to go from a rough design to a working mobile app by giving ChatGPT clear instructions, screenshots, and follow-up prompts.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a35a2314e1a9973546c/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a35a2314e1a9973546c?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 89, now() - (8 * interval '1 second'), true, 'You no longer need to wait until you''ve taken a CS class to ship something. Knowing how to brief an AI tool clearly is becoming as useful as knowing how to write an email.', 'Building a small thing and showing it is one of the strongest ways to stand out in applications, interviews, and conversations. AI lowers the cost of having something to show.', 'You don''t need to know how to code to ship a small app. You need to know how to describe what you want clearly.', 'Shipping something small is one of the fastest ways to learn what you actually like to build. As you think about a tool, app, or page you wish existed, what is the simplest version of it you could try to make this month?'),
    ('mindsets-gumlet-009', 'mirroring-and-emotion', 'Mirroring and emotion', 'A behavior researcher explains how mirror neurons spread real emotion between people, and why a fake smile measurably fails to move anyone.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a35a2314e1a9973548b/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a35a2314e1a9973548b?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 42, now() - (9 * interval '1 second'), true, 'How you actually feel walking into a room leaks into how other people respond to you. That matters for interviews, group projects, and pitches.', 'You can prepare your answers all you want, but if you are not actually interested in the role, the other person will sense it. Picking opportunities you can show up to honestly is part of the work.', 'Real emotion spreads. Fake emotion does not.', 'People pick up on whether your interest is genuine, even when they cannot say why. As you think about a job, club, or program you might apply for, is it something you could walk in genuinely excited about, or are you trying to perform excitement?'),
    ('mindsets-gumlet-010', 'money-is-a-tool', 'Money is a tool', 'A coach argues that how your body reacts to the word ''money'' often predicts how much of it you''ll end up with, and pushes the idea of treating money as a tool you respect rather than fear.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a396d3b523a974ebf6f/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a396d3b523a974ebf6f?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 71, now() - (10 * interval '1 second'), true, 'A lot of money habits get set before you ever earn much. Noticing your own reaction to the word is a free way to surface beliefs that might quietly hold you back.', 'How you talk about money shapes the salaries you ask for, the offers you accept, and the trade-offs you''ll make later. It''s worth examining before you''re negotiating real numbers.', 'Money is a tool, not a personality. Your relationship with it is mostly a story you can rewrite.', 'How you feel about money usually shapes how much of it you end up with. As you think about your own reaction to the word, would you say you treat money like an enemy, a stranger, or a tool you respect?'),
    ('mindsets-gumlet-011', 'shots-on-goal', 'Shots on goal', 'A founder explains why young people should optimize for urgency and many attempts up front, instead of slowly building one perfect plan they cannot yet evaluate.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a39a2314e1a99735550/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a39a2314e1a99735550?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 56, now() - (11 * interval '1 second'), true, 'Early on, you don''t know enough to pick the right thing on the first try. The way you find a good direction is by trying enough wrong ones quickly.', 'Treat your first few years after school as a season of high-volume, low-cost attempts. The goal is data about yourself, not a perfect career on attempt one.', 'Early on, you don''t know enough to pick the right goal. Take more shots faster so you learn which goal is actually right.', 'When you don''t yet know what ''great'' looks like, the only honest path is to try more things faster. As you think about the year ahead, what is one extra shot on goal you could take that you''d normally save for later?'),
    ('mindsets-gumlet-012', 'shut-up-suit-up-show-up', 'Shut up, suit up, show up', 'An author shares a three-word morning motto: stop complaining, do your homework, and bring the best you can to whatever is in front of you today.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a39a2314e1a99735556/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a39a2314e1a99735556?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 43, now() - (12 * interval '1 second'), true, 'Most days don''t reward big plans; they reward whether you actually showed up prepared. The clip names a simple discipline that holds up under pressure.', 'Plans only work if they survive ordinary days. A short personal rule you can run on a tired Tuesday is more useful than a long strategy you can''t repeat.', 'Most days don''t need a strategy. They need you to stop complaining, prepare, and show up.', 'Plans only work if they survive ordinary days. As you think about a stretch of week ahead, what would change if you ran on a simple rule like ''stop complaining, prepare, show up'' instead of trying to optimize every choice?'),
    ('mindsets-gumlet-013', 'temptation-bundling', 'Temptation bundling', 'A behavioral scientist describes pairing a task you dread with a reward you only allow yourself during that task, so the dreaded thing actually gets done.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a39a2314e1a9973555c/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a39a2314e1a9973555c?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 63, now() - (13 * interval '1 second'), true, 'Discipline alone runs out. Temptation bundling is a small system you can set up once to make studying, exercising, or chores feel less like a fight.', 'Your week is full of tasks you keep avoiding. Bundling one with a reward that exists nowhere else can move it from ''should do'' to ''will do'' without extra willpower.', 'Pair a task you dread with a reward you only allow during that task. The trick only works if you never break the rule.', 'Willpower alone runs out fast, but a small system can carry the load. As you think about something you keep avoiding this week, what reward could you bundle with it that you''d only allow yourself in that one moment?'),
    ('mindsets-gumlet-014', 'schedule-your-worry-time', 'Schedule your worry time', 'Shaan Puri explains a trick he uses for big decisions: put 30 minutes on the calendar as ''worry time'' so you stop worrying about it during the rest of the week.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a3a6d3b523a974ebf7d/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a3a6d3b523a974ebf7d?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 77, now() - (14 * interval '1 second'), true, 'Unscheduled worry leaks into everything else and quietly stops you from making decisions at all. Putting it in one slot frees the rest of your time.', 'A lot of student stress is about decisions you cannot make today anyway. Scheduling when you''ll think about them lets you actually study, work, and rest in between.', 'If you don''t pick a time to worry, you worry all the time. Schedule it so the rest of your week is yours.', 'Worry that has no time slot quietly takes over every slot. As you think about something that keeps interrupting your week, what would change if you scheduled a single 30-minute window to think about it and ignored it until then?'),
    ('mindsets-gumlet-015', 'interview-red-flags', 'Interview red flags', 'An entrepreneur lists the things candidates do that take them out of the running: trashing their last boss, blaming everything on others, and asking about work-life balance up front.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a3ca2314e1a997355b9/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a3ca2314e1a997355b9?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 92, now() - (15 * interval '1 second'), true, 'A lot of candidates lose offers in the first ten minutes for reasons no one tells them. Hearing them said out loud is a free upgrade.', 'Interview prep usually focuses on what to say. This clip is mostly about what not to say, which is just as important when you''re competing for a real role.', 'How you talk about your last boss is how the next one assumes you''ll talk about them. Most candidates lose offers in the first ten minutes.', 'Interviews are often won or lost in the first ten minutes for reasons no one explains. As you think about how you talk about past jobs, schools, or coaches, would a hiring manager hear someone who takes ownership, or someone who blames others?'),
    ('mindsets-gumlet-016', 'the-thiel-fellowship-and-the-college-bundle', 'The Thiel Fellowship and the college bundle', 'A founder unpacks Peter Thiel''s argument that college is a bundle (insurance, filter, social network, education) and his $100,000 grant for people who skip it to build something instead.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a3ca2314e1a997355c4/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a3ca2314e1a997355c4?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 109, now() - (16 * interval '1 second'), true, 'Most students treat college as one thing. Seeing it as several different things you could in theory get separately changes how you evaluate the cost.', 'You don''t have to drop out of college to use this idea. Picking the parts of the bundle you actually need, and being honest about the parts you don''t, is real planning.', 'College is several different things in one package. Knowing which parts you actually need changes the trade-off.', 'School is really several things bundled together: a credential, a social network, an environment to learn, and an insurance policy. As you think about your own path, which part of that bundle matters most to you, and could any of the other parts come from somewhere else?'),
    ('mindsets-gumlet-017', 'money-is-not-a-measure-of-worth', 'Money is not a measure of worth', 'A finance writer talks about the most dangerous lesson kids can learn about money: that net worth and personal worth are the same thing. He pushes for treating money as a tool that makes you happier instead.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a3c89ec653eb39ce837/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a3c89ec653eb39ce837?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 78, now() - (17 * interval '1 second'), true, 'It''s easy to absorb the idea that rich people are valuable and poor people are not. The clip pushes back on that quietly and clearly.', 'When you''re ranking jobs, programs, or paths by income alone, you''re answering a smaller question than you think. Asking ''what would actually make me happier?'' usually reorders the list.', 'Don''t rank people by net worth. Ask instead what money can actually do to make you happier.', 'It is easy to slide into ranking people, including yourself, by income. As you think about a path you''re considering, are you weighing it by what it pays, or by what it could actually do to make your life better?'),
    ('mindsets-gumlet-018', 'make-your-own-ground', 'Make your own ground', 'Writer David Epstein traces how he went from studying the carbon cycle in the Arctic to writing the Sports Illustrated cover story on sudden cardiac death in athletes, by following one personal question across two careers.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a3ca2314e1a997355dc/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a3ca2314e1a997355dc?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 77, now() - (18 * interval '1 second'), true, 'Most careers aren''t a straight line. The story shows how merging two interests you already have can create a role nobody else is qualified for.', 'If you only compare yourself to people on the same track, you''re stuck competing for the same spots. The clip is a model for inventing your own track by combining what''s already true about you.', 'When you can''t beat people on their track, build your own. Two interests combined can become a job nobody else is qualified for.', 'The most interesting careers are often built at the seam between two things you already care about. As you think about two of your own interests that look unrelated, what would it look like to do something useful that needs both?'),
    ('mindsets-gumlet-019', 'humor-as-a-tool', 'Humor as a tool', 'Storyteller Matthew Dicks argues that humor is one of the most underused tools in school and work. A laugh in the first 30 seconds quietly tells people you know what you''re doing.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a3da2314e1a9973563e/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a3da2314e1a9973563e?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 27, now() - (19 * interval '1 second'), true, 'Students often treat humor as the opposite of being taken seriously. The clip names it as a skill that earns trust faster than almost anything else.', 'Presentations, group work, and interviews all reward people who can land one easy laugh early. It''s a practiceable skill, not a personality trait.', 'A laugh in the first 30 seconds tells people you know what you''re doing. Humor is a skill, not a personality.', 'Humor changes how people listen to you for the rest of a conversation. As you think about your next presentation, interview, or pitch, what is one small, honest moment in it that could open with a laugh?'),
    ('mindsets-gumlet-020', 'ask-better-questions', 'Ask better questions', 'Vanessa Van Edwards shows how the brain reaches for hits, not misses, so ''working on anything exciting lately?'' lands very differently than ''been busy?''', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a3e89ec653eb39ce8a1/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a3e89ec653eb39ce8a1?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 65, now() - (20 * interval '1 second'), true, 'Small talk is how most new opportunities start. The default questions (''how are you?'', ''where are you from?'') almost never lead anywhere.', 'Networking, info chats, and first days all run on a few short conversations. Trading the default questions for sharper ones is one of the highest-leverage social upgrades you can make.', 'The brain searches for hits, not misses. Change the question and you change the conversation.', 'The brain answers whatever question it''s given, so ''been busy?'' and ''working on anything exciting?'' surface completely different stories. As you think about the next time you meet someone new, what is one better question you could ask instead of the default?'),
    ('mindsets-gumlet-021', 'expand-your-sense-of-identity', 'Expand your sense of identity', 'Behavioral scientist Maya Shankar describes how most people lock too early into a narrow identity built from fairly random life events, and how a more expansive, malleable sense of self protects you when life shifts.', 'video', 'https://video.gumlet.io/69729496f87206f059e424e0/6a106a3ea2314e1a9973565e/thumbnail-1-0.png?format=auto', 'https://play.gumlet.io/embed/6a106a3ea2314e1a9973565e?background=false&autoplay=false&loop=false&disable_player_controls=false', 'vertical', 69, now() - (21 * interval '1 second'), true, 'If your identity is one thing (''I''m the athlete'', ''I''m the smart one''), one bad season can knock the whole thing over. The clip argues for more flexible identities that handle change better.', 'Career planning often forces an identity question early: ''I''m pre-med'', ''I''m in engineering''. Keeping your identity broader gives you room to pivot without feeling like you''ve lost yourself.', 'If your identity is one thing, one bad season can break it. A more expansive identity protects you when life shifts.', 'If your identity is built around just one thing, one bad season can knock the whole thing over. As you think about how you describe yourself today, what would it sound like to hold that identity a little more loosely?')
  on conflict (id) do update
    set slug = excluded.slug,
        title = excluded.title,
        description = excluded.description,
        content_type = excluded.content_type,
        thumbnail_url = excluded.thumbnail_url,
        video_url = excluded.video_url,
        video_orientation = excluded.video_orientation,
        video_duration = excluded.video_duration,
        published_at = excluded.published_at,
        is_published = excluded.is_published,
        why_it_matters = excluded.why_it_matters,
        planning_connection = excluded.planning_connection,
        takeaway = excluded.takeaway,
        reflection = excluded.reflection,
        updated_at = now();

  get diagnostics actual_count = row_count;
  if actual_count <> expected_count then
    raise exception 'Expected % mindset gumlet rows upserted, got %', expected_count, actual_count;
  end if;

  insert into public.content_categories (content_id, category_id)
  select links.content_id, categories.id
  from (
    values
    ('mindsets-gumlet-001', 'mindsets'),
    ('mindsets-gumlet-002', 'mindsets'),
    ('mindsets-gumlet-003', 'mindsets'),
    ('mindsets-gumlet-004', 'mindsets'),
