    ('mindsets-gumlet-008', 'mindsets'),
    ('mindsets-gumlet-009', 'mindsets'),
    ('mindsets-gumlet-010', 'mindsets'),
    ('mindsets-gumlet-011', 'mindsets'),
    ('mindsets-gumlet-012', 'mindsets'),
    ('mindsets-gumlet-013', 'mindsets'),
    ('mindsets-gumlet-014', 'mindsets'),
    ('mindsets-gumlet-015', 'mindsets'),
    ('mindsets-gumlet-016', 'mindsets'),
    ('mindsets-gumlet-017', 'mindsets'),
    ('mindsets-gumlet-018', 'mindsets'),
    ('mindsets-gumlet-019', 'mindsets'),
    ('mindsets-gumlet-020', 'mindsets'),
    ('mindsets-gumlet-021', 'mindsets')
  ) as links(content_id, category_slug)
  join public.categories categories on categories.slug = links.category_slug
  on conflict (content_id, category_id) do nothing;

  select count(*)
    into linked_count
  from public.content_categories cc
  join public.categories c on c.id = cc.category_id
  where cc.content_id in ('mindsets-gumlet-001', 'mindsets-gumlet-002', 'mindsets-gumlet-003', 'mindsets-gumlet-004', 'mindsets-gumlet-005', 'mindsets-gumlet-006', 'mindsets-gumlet-007', 'mindsets-gumlet-008', 'mindsets-gumlet-009', 'mindsets-gumlet-010', 'mindsets-gumlet-011', 'mindsets-gumlet-012', 'mindsets-gumlet-013', 'mindsets-gumlet-014', 'mindsets-gumlet-015', 'mindsets-gumlet-016', 'mindsets-gumlet-017', 'mindsets-gumlet-018', 'mindsets-gumlet-019', 'mindsets-gumlet-020', 'mindsets-gumlet-021')
    and c.slug = 'mindsets';

  if linked_count <> expected_count then
    raise exception 'Expected % mindset gumlet category links, got %', expected_count, linked_count;
  end if;
end $$;
